// Package symbols holds the Yaegi bindings for the standard-library packages
// in allowlist.Packages. The zz_*.go files are generated by cmd/hafagen from
// the pinned Go toolchain and are not committed.
package symbols

import "reflect"

// Symbols maps "importpath/name" keys to exported package values, in the
// layout interp.Use expects.
var Symbols = map[string]map[string]reflect.Value{}
